
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_x_t_pbe2_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_x_t_pbe2", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.384717729849844e+00, -4.304716874489256e+00, -4.192855674024488e+00, -4.038409393479584e+00, -3.829051794387235e+00, -3.552797925034341e+00, -3.202497689837888e+00, -2.784122873179987e+00, -2.327952243098348e+00, -1.882598159926936e+00, -1.365447574451615e+00, -7.416415801658253e-01, -6.092158853976294e-01, -5.205465660048321e-01, -4.127506139934491e-01, -3.358677483281033e-01, -3.261710449135020e-01, -2.774149348684877e-01, -8.140811009951809e-02, -9.323789016654071e-03]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


